import{_ as s,o as a,c as n,a2 as t}from"./chunks/framework.Boholvbs.js";const h=JSON.parse('{"title":"xsync-config(5)","description":"Set personal defaults and understand which layer wins.","frontmatter":{"title":"xsync-config(5)","description":"Set personal defaults and understand which layer wins.","manual":"xsync-config(5)","manualName":"Environment & defaults","sectionNumber":"5"},"headers":[],"relativePath":"environment.md","filePath":"environment.md"}'),o={name:"environment.md"};function l(c,e,r,d,i,p){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="xsync-config-5" tabindex="-1">xsync-config(5) <a class="header-anchor" href="#xsync-config-5" aria-label="Permalink to &quot;xsync-config(5)&quot;">​</a></h1><div class="manual-deck"><strong>Environment &amp; defaults</strong><p>Set personal defaults and understand which layer wins.</p></div><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES {#files}&quot;">​</a></h2><p>The default config is <code>$XDG_CONFIG_HOME/xsync/config</code>, or <code>~/.config/xsync/config</code> when XDG_CONFIG_HOME is unset. A missing default file is ignored. An explicitly selected missing file is an error.</p><div class="example-caption">A defaults file</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#858585;"># ~/.config/xsync/config</span></span>
<span class="line"><span style="color:#DEDEDE;">--progress</span></span>
<span class="line"><span style="color:#DEDEDE;">--jobs=</span><span style="color:#DEDEDE;">4</span></span>
<span class="line"><span style="color:#DEDEDE;">--exclude </span><span style="color:#DEDEDE;">&#39;scratch files&#39;</span></span></code></pre></div><p>Blank lines and full-line comments are allowed. Quoting splits words; variables, commands, and <code>~</code> are never expanded. Defaults contain flags and values, with transfer paths on the command line. Control actions such as install/server/help/version are not defaults.</p><h2 id="precedence" tabindex="-1">PRECEDENCE <a class="header-anchor" href="#precedence" aria-label="Permalink to &quot;PRECEDENCE {#precedence}&quot;">​</a></h2><p>For scalar options and on/off flags: <strong>command-line flags → environment → config</strong>. Within a layer, the last value wins. Repeatable options accumulate from config, then environment, then command-line flags; <code>--filter=!</code> clears earlier filter rules.</p><div class="example-caption">An explicit command-line override</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">export XSYNC_OPTS=</span><span style="color:#DEDEDE;">&#39;--jobs=8 --no-progress&#39;</span></span>
<span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">--progress</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><h2 id="environment" tabindex="-1">ENVIRONMENT <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;ENVIRONMENT {#environment}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Variable</th><th scope="col">Meaning</th></tr></thead><tbody><tr><td><code>XSYNC_CONFIG</code></td><td>Alternate config path; an empty value disables config</td></tr><tr><td><code>XSYNC_OPTS</code></td><td>Shell-quoted default option string</td></tr><tr><td><code>XSYNC_PROGRESS</code></td><td>0 disables; 1 enables; auto retains defaults; explicit flags win</td></tr><tr><td><code>XSYNC_FALLBACK</code></td><td>0 disables fallback; --fallback overrides it</td></tr><tr><td><code>XSYNC_RSH</code></td><td>Remote shell, ahead of RSYNC_RSH and defaults</td></tr><tr><td><code>RSYNC_RSH</code></td><td>Remote shell when higher-priority settings are absent</td></tr><tr><td><code>XSYNC_REMOTE_PATH</code></td><td>Extra remote helper lookup path</td></tr><tr><td><code>XSYNC_RELEASE_DIR</code></td><td>Release artifacts for explicit remote install</td></tr><tr><td><code>NO_COLOR</code></td><td>Disable color escapes in progress</td></tr></tbody></table></div><h2 id="remote-shell" tabindex="-1">REMOTE SHELL PRECEDENCE <a class="header-anchor" href="#remote-shell" aria-label="Permalink to &quot;REMOTE SHELL PRECEDENCE {#remote-shell}&quot;">​</a></h2><p><code>--rsh</code>/<code>-e</code>, then <code>XSYNC_RSH</code>, then <code>RSYNC_RSH</code>, then a shell in XSYNC_OPTS, then config, then <code>ssh</code>. Empty shell values are rejected.</p><div class="example-caption">Set the remote shell through the environment</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">export XSYNC_RSH=</span><span style="color:#DEDEDE;">&#39;ssh -p 2222&#39;</span></span>
<span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-azP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> user@host:/backup/</span></span></code></pre></div><h2 id="deterministic" tabindex="-1">CONTROL DEFAULTS EXPLICITLY <a class="header-anchor" href="#deterministic" aria-label="Permalink to &quot;CONTROL DEFAULTS EXPLICITLY {#deterministic}&quot;">​</a></h2><div class="example-caption">Disable personal defaults and require native execution</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">XSYNC_CONFIG=</span><span style="color:#DEDEDE;">&#39;&#39;</span><span style="color:#DEDEDE;"> XSYNC_OPTS=</span><span style="color:#DEDEDE;">&#39;&#39;</span><span style="color:#DEDEDE;"> xs </span><span style="color:#DEDEDE;">--no-fallback</span><span style="color:#DEDEDE;"> --no-progress</span><span style="color:#DEDEDE;"> -a</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>Check inherited <code>XSYNC_*</code> and <code>RSYNC_RSH</code> variables when making a fully controlled script. Explicit flags override progress and fallback defaults; supply <code>-e</code> if the remote shell must also be fixed.</p>`,21)])])}const D=s(o,[["render",l]]);export{h as __pageData,D as default};
